    "text": "うん、それについてはほかのメンバーがもう動いてくれてるんだ。でも、それだけじゃ足りないから、新しい方法での資金調達も考えないといけないんだけど、今やろうと思ってるのは、これまで無料だった入場券を有料にすることと、大学校内で寄付を募ること。",
