    "text": "はい。健康保険の手続きは保険課でお願いします。運転免許証の記載事項変更は、警察署の管轄です。市役所のすぐ隣の建物が警察署です。 警察署で手続きをされる際に、新しい住所が証明できるもの、たとえば、公共料金の領収書や消印つきの郵便物が必要になりますが、今お持ちですか。",
