    "unitId": "n1:task-comprehension:2017-12:2:line-7",
    "text": "では、ご用意ができましたら、番号でお呼びしますので、隣の交付窓口にお越しください。お客様の番号は22番です。ただ、今二、三十分はかかるかと。その間に、保険課で健康保険のお手続きをどうぞ、十分もかからないと思いますから。",
