    "unitId": "n1:task-comprehension:2017-12:4:line-5",
    "text": "あっ、外に出る前に、他のスタッフ、誰でもいいから在庫の数を確認するよう頼んでくれる？確認でき次第すぐわたしに報告するよう伝えて。在庫数がわかったら、大谷君にも携帯で知らせるから、列の先頭からお客様の数を数えて。商品が行き届かないかもしれない方には、その旨伝えてくれるかな。こういうのは出来るだけ早く伝えておいたほうがいいから。",
