    "unitId": "n1:task-comprehension:2017-12:4:line-7",
    "text": "あ、そうだ。今日お渡しできないお客様には、次の入荷予定日を知らせておいたほうがいいね。本社に問い合わせて、入荷までに何日かかるか聞いておくわ。あとで在庫数の連絡するとき、一緒に言うから、今日渡せない方に伝えてね。",
