    "text": "ほら、前に話してくれたでしょう。喫茶店で親が小さな子に携帯で動画を見せて、ほったらかしにしている様子を見て、問題がないのか疑問に思ったって。そのあたりのことを書くと、読み手の興味を惹くことができると思うよ。",
