    "questionId": "n1:task-comprehension:2017-12:6",
    "unitId": "n1:task-comprehension:2017-12:6:line-6",
    "text": "うん、高級食品の売上額が上昇しているのはこれまでの調査結果を見れば一目瞭然だから、わたしも路線としてはいいと思うんだ。でも、具体的に何が消費者の高級食品に対する購買意欲を刺激しているのかについては、ほとんどリサーチされてなくて、会議でその点について独自に調べてみようという話になってね。それで、それを吉田さんにお願いしたいと思ってるんだ。",
